const executeDeleteCommand = (item) => {
  if (item) {
    const index = listItems.value.indexOf(item);
    if (index !== -1) {
      listItems.value.splice(index, 1);
    }
  } else if (selectedIndex.value !== -1) {
    listItems.value.splice(selectedIndex.value, 1);
    selectedIndex.value = -1;
  }
};

